import unittest
import weekly_archive as app

class Behavior(unittest.TestCase):
    def test_year_boundaries(self):
        from datetime import date
        for day, expected in [(date(2021, 1, 1), '2020-W53'), (date(2018, 12, 31), '2019-W01'), (date(2022, 1, 2), '2021-W52'), (date(2021, 1, 4), '2021-W01'), (date(2020, 12, 31), '2020-W53')]:
            with self.subTest(day=day):
                self.assertEqual(app.week_key(day), expected)
    def test_normal_dates(self):
        from datetime import date
        self.assertEqual(app.week_key(date(2026, 5, 4)), '2026-W19')
        self.assertEqual(app.week_key(date(2024, 2, 29)), '2024-W09')

    def test_additional_behavior(self):
        from datetime import date
        self.assertEqual(app.week_key(date(2016, 1, 3)), '2015-W53')

if __name__ == '__main__':
    unittest.main()

